import requests
import re

# Try to find the paper on ResearchGate specifically
url = 'https://www.researchgate.net/search?query=%22An Insight into Goat Cheese%22+Ilias+Lagkouvardos'

try:
    response = requests.get(url, timeout=10)
    if response.status_code == 200:
        print('Searching ResearchGate...')
        # Look for the specific paper
        if 'Gidotyri' in response.text and 'Microbiota' in response.text:
            print('Found paper with matching keywords!')
            # Extract the first result link
            match = re.search(r'href=\"([^\"]*researchgate\.net[^"]*paper[^"]*)\"', response.text)
            if match:
                paper_url = match.group(1)
                print(f'Paper URL: {paper_url}')
                # Try to access the paper page
                paper_response = requests.get(paper_url, timeout=10)
                if paper_response.status_code == 200:
                    print('Successfully accessed paper page')
                    print('Page content length:', len(paper_response.text))
                    # Look for PDF download link
                    pdf_match = re.search(r'href=\"([^\"]*\.pdf)\"', paper_response.text)
                    if pdf_match:
                        print(f'PDF available at: {pdf_match.group(1)}')
        else:
            print('No exact match found')
    else:
        print(f'Failed to access ResearchGate: {response.status_code}')
except Exception as e:
    print(f'Error: {e}')
""}

