import requests
import re

# Try searching with different variations
queries = [
    'An Insight into Goat Cheese: The Tales of Artisanal and Industrial Gidotyri Microbiota',
    'Ilias Lagkouvardos goat cheese microbiota',
    'Gidotyri microbiota Lagkouvardos'
]

base_url = 'https://scholar.google.com/scholar'

for query in queries:
    try:
        params = {'q': query}
        response = requests.get(base_url, params=params, timeout=10)
        if response.status_code == 200:
            print(f'Searching for: {query}')
            print('Response length:', len(response.text))

            # Look for the specific paper
            if 'Goat Cheese' in response.text and 'Gidotyri' in response.text:
                print('Found matching paper!')

                # Extract the first result link
                match = re.search(r'<a href=\"([^\"]*scholar\.google\.com[^"]*citation[^"]*)\"', response.text)
                if match:
                    scholar_url = match.group(1)
                    print(f'Google Scholar URL: {scholar_url}')

                    # Try to get the actual paper URL from the citation page
                    citation_response = requests.get(scholar_url, timeout=10)
                    if citation_response.status_code == 200:
                        # Look for PDF link
                        pdf_match = re.search(r'href=\"([^\"]*\.pdf)\"', citation_response.text)
                        if pdf_match:
                            print(f'PDF link found: {pdf_match.group(1)}')
            else:
                print('No exact match')
            print()
    except Exception as e:
        print(f'Error searching {query}: {e}')
""}

