from urllib.parse import quote

# Try to find the paper using different academic databases
databases = [
    'https://www.frontiersin.org/search?query=' + quote('Goat Cheese Gidotyri Microbiota Lagkouvardos'),
    'https://www.mdpi.com/search?q=' + quote('Goat Cheese Gidotyri'),
    'https://link.springer.com/search?query=' + quote('Gidotyri goat cheese microbiota')
]

for db_url in databases:
    try:
        response = requests.get(db_url, timeout=10)
        if response.status_code == 200:
            print(f'Trying: {db_url}')
            print('Response length:', len(response.text))

            # Look for the specific paper
            if 'An Insight into Goat Cheese' in response.text or 'Gidotyri' in response.text:
                print('Found potential match!')

                # Extract paper links
                if 'frontiers' in db_url:
                    # Frontiers format
                    matches = re.findall(r'<a[^>]*href=\"([^\"]*articles[^"]*)\"[^>]*>([^<]+)</a>', response.text)
                    for url, title in matches:
                        if 'Goat' in title or 'Cheese' in title:
                            print(f'Frontiers paper: {title}')
                            print(f'URL: {url}')
                elif 'mdpi' in db_url:
                    # MDPI format
                    matches = re.findall(r'<a[^>]*href=\"([^\"]*html[^"]*)\"[^>]*>([^<]+)</a>', response.text)
                    for url, title in matches:
                        if 'Goat' in title or 'Cheese' in title:
                            print(f'MDPI paper: {title}')
                            print(f'URL: {url}')
                elif 'springer' in db_url:
                    # Springer format
                    matches = re.findall(r'<a[^>]*href=\"([^\"]*article[^"]*)\"[^>]*>([^<]+)</a>', response.text)
                    for url, title in matches:
                        if 'Goat' in title or 'Cheese' in title:
                            print(f'Springer paper: {title}')
                            print(f'URL: {url}')
            print()
    except Exception as e:
        print(f'Error accessing {db_url}: {e}')
        print()
""}

