import requests

# Try to find the paper using a different search approach
url = 'https://www.google.com/search?q=%22An Insight into Goat Cheese%22+Hafnia+alvei+goat'

try:
    response = requests.get(url, timeout=15)
    if response.status_code == 200:
        print('Searching with Hafnia alvei and goat keywords...')
        print('Response length:', len(response.text))

        # Look for any mentions of the paper
        if 'An Insight into Goat Cheese' in response.text:
            print('Found the exact paper with Hafnia alvei context!')

            # Extract content around Hafnia alvei mentions
            lines = response.text.split('\n')
            for i, line in enumerate(lines):
                if 'Hafnia alvei' in line.lower():
                    print(f'Found Hafnia alvei at line {i}: {line.strip()}')
                    # Get surrounding context
                    start = max(0, i-2)
                    end = min(len(lines), i+3)
                    for j in range(start, end):
                        print(f'  Context {j}: {lines[j].strip()}')
        else:
            print('Paper not found in this search')

    else:
        print(f'Search failed with status code: {response.status_code}')

except Exception as e:
    print(f'Error: {e}')
""}

